    { t: 'fill', q: '选词填空（怎么着　过剩　这么说　一路　馊主意　短缺　人性化）', items: [['（___），你根本就不知道这件事？', '这么说'], ['别的都好说，就是资金（___）的问题解决不了。', '短缺'], ['劳动力（___）是农村的大问题。', '过剩'], ['你这是什么（___）呀？根本行不通。', '馊主意'], ['鸡蛋价格（___）下跌，都没人想养鸡了。', '一路'], ['那个商场只有上楼有电梯，下楼就得走着，也太不（___）了。', '人性化'], ['朋友结婚，咱们（___）也得表示表示吧？', '怎么着']] }
