    { t: 'match', q: '在词语和它们的意思之间连线', items: [['如鱼得水', '像鱼在水中一样，比喻得到极其满意的环境，自己感到很自如。'], ['萝卜白菜，各有所爱', '每个人的兴趣、爱好不一样。'], ['用武之地', '施展才能、本领的地方。']] },
    { t: 'fill', q: '用上面的词语填空（如鱼得水　萝卜白菜，各有所爱　用武之地）', items: [['他在这个单位简直是（___），工作顺利极了。', '如鱼得水'], ['虽说（___），可你的媳妇就是我的儿媳妇，怎么着也得让我看着也顺眼吧。', '萝卜白菜，各有所爱|萝卜白菜各有所爱'], ['这回你总算找到（___）了，你可得珍惜这个机会呀！', '用武之地']] },
    { t: 'fill', q: '选词填空（实惠　青睐　萝卜白菜，各有所爱　园地　创意　之久　素　之众　就　而非）', items: [['这个（___）不错，挺新鲜的。', '创意'], ['这个餐馆经济（___），很受老百姓的欢迎。', '实惠'], ['这本杂志越来越多地受到年轻人的（___）。', '青睐'], ['她出生在南方一个（___）有“人间天堂”美称的地方。', '素'], ['虽说（___）是天经地义的，可看电视的时候就麻烦了。', '萝卜白菜，各有所爱|萝卜白菜各有所爱'], ['今天咱们只（___）保修问题展开讨论，不牵涉别的。', '就'], ['《学汉语》杂志为留学生提供了一个发表作品的（___）。', '园地'], ['我们的帮助对他们一定是雪中送炭，（___）锦上添花。', '而非'], ['北冰洋的严冬长达半年（___），最冷季节的平均气温在-40℃左右。', '之久'], ['中国网民数量年底可望达到一亿（___）。', '之众']] }
