    { t: 'open', q: '根据课文第二段内容，用自己的话说一说', items: [['刘加的头发是什么样的？父母是什么态度？', '剪得一撮一撮的，一半染黄一半染白；父母很保守，父亲大发脾气，让他洗掉，还用棍子打他。'], ['为什么说刘加为头发进行的斗争很“悲壮”？', '他咬着牙坚持不把头发染回来，最后赢了，可被打得在床上躺了三天，走路都不利索。']] },
    { t: 'fill', q: '选词填空（早期　利索　反客为主　翻来覆去　话题一转　再说　花样　折腾）', items: [['他到我们家一点儿都不客气，简直有点儿（___）了。', '反客为主'], ['随后，她（___），说现在可大不一样了。', '话题一转'], ['如今武术也（___）翻新，又像是武术，又像是表演。', '花样'], ['他的病属于（___），好治，发现太晚就危险了。', '早期'], ['作文要写得简洁点儿，话别（___）地说。', '翻来覆去'], ['你念的专业不太适合我们公司。（___），我们现在也不缺人。', '再说'], ['像她这样几年就能（___）成名人的女人可不多。', '折腾'], ['小张可不简单，脑子聪明，做事也（___）。', '利索']] }
